using UnityEngine;using UnityEditor;using System.Linq;using Codice.Presentation;
public static class AudioDeviceState{public static string Run(){var a=GameAudio.Instance;string report="pause="+AudioListener.pause+" volume="+AudioListener.volume+" rate="+AudioSettings.outputSampleRate+" dsp="+AudioSettings.dspTime+" background="+Application.runInBackground+" editorMute="+EditorUtility.audioMasterMute+" listeners="+Object.FindObjectsByType<AudioListener>().Length;Application.runInBackground=true;foreach(var s in a.GetComponentsInChildren<AudioSource>())if(s.clip&&s.loop)s.Play();return report;}}
